"""Actual native boxed error attribution, with original authored errors intact."""
import argparse,json,pathlib,subprocess,tempfile,xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);p.add_argument('--directory',required=True,type=pathlib.Path);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();rows=[]
common='import{defineNativeSuite}from '+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';import{writeFileSync}from'node:fs';"
def run(name,source,code=0):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+'\n'+source);cmd=[str(a.executable),'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html')];v=subprocess.run(cmd,capture_output=True,timeout=15);(root/'stdout.bin').write_bytes(v.stdout);(root/'stderr.bin').write_bytes(v.stderr);assert v.returncode==code and not v.stderr,(name,v.returncode,v.stdout,v.stderr);r=json.loads((root/'actual.json').read_text());props={p.attrib['name']:p.attrib.get('value','')for p in ET.parse(root/'actual.xml').findall('.//property')};html=(root/'actual.html').read_text()
 for step in r['steps']:
  attribution=step.get('errorAttribution')
  if attribution:
   assert step['box'] and attribution['stepId']==step['id'] and attribution['primary'] is True and attribution['location']['origin']=='callsite'
   assert attribution['location']==step.get('boxCaller',step.get('boxCallsite'))
   prefix='native.step'+step['id']+'.errorAttribution.';assert props[prefix+'file']==attribution['location']['file'] and props[prefix+'line']==str(attribution['location']['line']) and props[prefix+'column']==str(attribution['location']['column']) and props[prefix+'primary']=='true';assert 'Primary boxed error location'in html and 'original authored error and stack preserved'in html
 rows.append({'scope':name,'actualExitCode':v.returncode,'report':str(root/'actual.json')});return root,r
source="""const original=new Error('actual authored stack');const stack=original.stack;
async function helper(i){
  return i.step('boxed helper',()=>{writeFileSync(new URL('./original.txt',import.meta.url),stack);throw original},{box:true});
}
export default defineNativeSuite({tests:[{title:'caught original',run:async(_,i)=>{
  try{await helper(i);assert.fail('actual error required')}catch(e){assert.equal(e,original);assert.equal(e.stack,stack)}
}}]});"""
root,r=run('genuine-helper-caller-and-original-stack',source);step=r['steps'][0];assert step['status']=='failed'and step['error']==step['receiptError']==(root/'original.txt').read_text();assert step['location']['line']==4 and step['errorAttribution']['location']['line']==7 and step['errorAttribution']['kind']=='boxedCaller',step;assert step['errorAttribution']['location']['file']==str(root/'suite.mjs')
root,r=run('unboxed-original-remains-unattributed',"export default defineNativeSuite({tests:[{title:'raw',run:async(_,i)=>{const original=Error('raw');await assert.rejects(i.step('unboxed',()=>{throw original}),e=>e===original)}}]});");assert r['steps'][0]['status']=='failed'and 'errorAttribution'not in r['steps'][0]and 'box'not in r['steps'][0]
root,r=run('explicit-location-does-not-counterfeit-captured-caller',"async function helper(i){return i.step('declared and boxed',()=>{throw Error('real')},{box:true,location:{file:'author-declared.ts',line:123,column:45}})}\nexport default defineNativeSuite({tests:[{title:'explicit',run:async(_,i)=>{await assert.rejects(helper(i))}}]});");step=r['steps'][0];assert step['location']=={'file':'author-declared.ts','line':123,'column':45,'origin':'explicit'}and step['errorAttribution']['location']['file']==str(root/'suite.mjs')and step['boxCallsite']['origin']=='callsite'
root,r=run('primitive-author-rejection-is-preserved',"export default defineNativeSuite({tests:[{title:'primitive',run:async(_,i)=>{try{await i.step('primitive',()=>{throw 17},{box:true});assert.fail('required rejection')}catch(value){assert.equal(value,17)}}}]});");assert r['steps'][0]['status']=='failed'and r['steps'][0]['errorAttribution']['primary']
root,r=run('nested-boxes-keep-own-native-identities',"export default defineNativeSuite({tests:[{title:'nested',run:async(_,i)=>{await assert.rejects(i.step('outer',()=>i.step('inner',()=>{throw Error('nested real')},{box:true}),{box:true}))}}]});");parent,child=r['steps'];assert child['parentId']==parent['id']and all(s['errorAttribution']['stepId']==s['id']for s in r['steps'])and parent['receiptError']==child['receiptError']
root,r=run('successful-box-has-no-invented-error',"export default defineNativeSuite({tests:[{title:'success',run:async(_,i)=>assert.equal(await i.step('returns',()=>17,{box:true}),17)}]});");assert r['steps'][0]['status']=='passed'and r['steps'][0]['box']and 'errorAttribution'not in r['steps'][0]
root,r=run('noninvoked-box-has-no-error-attribution',"export default defineNativeSuite({tests:[{title:'omitted',run:(_,i)=>i.step.skip('not invoked',()=>assert.fail('FORBIDDEN'),{box:true})}]});");assert r['steps'][0]['receipt']=='notInvoked'and r['steps'][0]['box']and 'errorAttribution'not in r['steps'][0]
root,r=run('native-timeout-keeps-original-late-raw-error',"export default defineNativeSuite({tests:[{title:'timeout',run:async(_,i)=>{await assert.rejects(i.step('late',async()=>{await new Promise(r=>setTimeout(r,40));throw Error('genuine late original')},{box:true,timeout:10}),/deadline|timeout/i)}}]});");step=r['steps'][0];assert step['status']=='timedOut'and step['receipt']=='settled'and 'genuine late original'in step['receiptError']and step['callbackReceiptMonotonicMs']>=step['endedMonotonicMs']and step['errorAttribution']['primary']
root,r=run('real-hook-owns-boxed-attribution',"export default defineNativeSuite({hooks:{beforeEach:[{run:async(_,i)=>{await assert.rejects(i.step('hook box',()=>{throw Error('hook original')},{box:true}))}}]},tests:[{title:'body',run:()=>{}}]});");assert r['steps'][0]['callbackKind']=='beforeEach'and r['steps'][0]['errorAttribution']['stepId']==r['steps'][0]['id']
root,r=run('native-retries-keep-distinct-boxed-records',"export default defineNativeSuite({tests:[{title:'retry',retries:1,run:(_,i)=>i.step('attempt',()=>{if(!i.retry)throw Error('original first failure')},{box:true})}]});");assert r['summary']['flaky']==1 and len(r['steps'])==2 and r['steps'][0]['generation']!=r['steps'][1]['generation']and 'errorAttribution'in r['steps'][0]and 'errorAttribution'not in r['steps'][1]
(receipt/'report.json').write_text(json.dumps({'passed':len(rows),'scope':'Native boxed error attribution from genuine captured callsites; authored error values and stack text remain intact. Separate native JSON/JUnit/HTML attribution is primary; no claim of identical external reporter stack rewriting or unchanged whole upstream boxed reporter cases.','groups':rows},indent=2)+'\n');print('PASS',len(rows),'actual native boxed step groups')
